('019822af-b448-7557-b71b-4f290da3139f', 'Trace only', 'Allow all TRACE action on all resources', 'TRACE', '*', TRUE),
-- automatic generate with the program apiendpoints
('0198fb33-7333-76f9-bcb4-1af086de3e10', 'List identity providers'             , 'Retrieve every ENABLED identity provider, for the login page. Disabled providers stay configured and are not offered'                                                                                                                                                                                                                   , 'GET'   , '/auth/idp/available'                         , TRUE    ),
('01988e60-89e5-72ee-9db4-db5cd7535717', 'Handle IDP OAuth callback'           , 'Called by the frontend callback route with the state and code from the provider, never by the browser: JSON answer, no cookie, no redirect. Spends the state, exchanges the code with PKCE, resolves the identity by subject'                                                                                                           , 'GET'   , '/auth/idp/{idp_id}/callback'                 , TRUE    ),
('01a07319-1d32-7bd2-8ba0-f7da9aaaed0a', 'Initiate IDP link'                   , 'Build the authorization URL for linking a provider identity to the signed-in account. The only way an existing account gains one: the session proves the account, the provider proves the identity'                                                                                                                                     , 'GET'   , '/auth/idp/{idp_id}/link'                     , TRUE    ),
('01988e60-89e5-72ab-adb4-3eef95d1afd3', 'Initiate IDP login'                  , 'Build the authorization URL for a sign-in. The caller sends the browser there; the provider returns it to the frontend callback route with a state and a code'                                                                                                                                                                          , 'GET'   , '/auth/idp/{idp_id}/login'                    , TRUE    ),
('019894ba-6014-79cf-bff4-6668484cc7e3', 'Initiate IDP registration'           , 'Build the authorization URL for a registration. Same flow as a login; the callback creates the account when the provider vouches for the email and allows auto-provisioning'                                                                                                                                                            , 'GET'   , '/auth/idp/{idp_id}/register'                 , TRUE    ),
('0198f1e2-14ff-7678-afbe-9a627b0eaabd', 'List IDP types'                      , 'Retrieve a paginated list of all Identity Provider Types available for authentication.'                                                                                                                                                                                                                                                 , 'GET'   , '/auth/idp_types'                             , TRUE    ),
('0198f1e2-14ff-767c-971c-3904e0f2c484', 'Get IDP type'                        , 'Retrieve a specific Identity Provider Type by its unique identifier'                                                                                                                                                                                                                                                                    , 'GET'   , '/auth/idp_types/{idp_type_id}'               , TRUE    ),
('0198e7ea-3755-7a29-90ed-13245b54f074', 'List IDPs'                           , 'Retrieve paginated list of Identity Providers with optional filtering and sorting'                                                                                                                                                                                                                                                      , 'GET'   , '/auth/idps'                                  , TRUE    ),
('0198e7ea-3755-7a39-9dfc-717d83facf02', 'Create IDP'                          , 'Register a new Identity Provider with authentication configuration'                                                                                                                                                                                                                                                                     , 'POST'  , '/auth/idps'                                  , TRUE    ),
('0198e7ea-3755-7a2d-9ab0-83ccef188e37', 'Delete IDP'                          , 'Permanently remove an Identity Provider configuration'                                                                                                                                                                                                                                                                                  , 'DELETE', '/auth/idps/{idp_id}'                         , TRUE    ),
('0198e7ea-3755-7a3d-8baa-36126e5d1c48', 'Get IDP'                             , 'Retrieve a specific Identity Provider configuration by its unique identifier'                                                                                                                                                                                                                                                           , 'GET'   , '/auth/idps/{idp_id}'                         , TRUE    ),
('0198e7ea-3755-7a35-9e30-6a9392e8e7a1', 'Update IDP'                          , 'Modify an existing Identity Provider configuration'                                                                                                                                                                                                                                                                                     , 'PUT'   , '/auth/idps/{idp_id}'                         , TRUE    ),
('019822af-b448-755b-92ff-d167d37719c2', 'Authenticate user'                   , 'Authenticate with email and password to obtain access and refresh tokens.'                                                                                                                                                                                                                                                              , 'POST'  , '/auth/login'                                 , TRUE    ),
('019822af-b448-7562-a27f-0d02884f3477', 'Logout user'                         , 'End the session. The access token this request was authorised with is revoked immediately and stops working. The refresh token is revoked too when it is supplied in the body -- without it, that token stays valid until it expires and can still mint new access tokens, so pass it.'                                                 , 'DELETE', '/auth/logout'                                , TRUE    ),
('01991917-2720-7589-971b-cce23bf8a74b', 'Initiate password recovery'          , 'Request a password reset email with secure token.'                                                                                                                                                                                                                                                                                      , 'POST'  , '/auth/password/recover'                      , TRUE    ),
('01991917-2720-758d-8104-94a0368acecb', 'Reset password'                      , 'Set new password using the token from password recovery email.'                                                                                                                                                                                                                                                                         , 'POST'  , '/auth/password/reset'                        , TRUE    ),
('019822af-b448-756a-92b2-791a0e748162', 'Refresh access token'                , 'Obtain new access and refresh tokens using valid refresh token. The token spent is the one in the Authorization header; the body is optional and, if it carries a token, it must be the same one.'                                                                                                                                      , 'POST'  , '/auth/refresh'                               , TRUE    ),
('019822af-b448-7572-a268-4c7b20a70229', 'Register new user'                   , 'Create a new user account and send verification email.'                                                                                                                                                                                                                                                                                 , 'POST'  , '/auth/register'                              , TRUE    ),
('01a072df-d81d-78c8-a72b-6ea167cd50b2', 'Get token lifetimes'                 , 'Read how long the access and refresh tokens issued from now on will live, the bounds a change is validated against, the shipped defaults, and who last changed them'                                                                                                                                                                    , 'GET'   , '/auth/token_lifetimes'                       , TRUE    ),
('01a072df-d81d-7995-ad3e-92a0a4d0a4cf', 'Update token lifetimes'              , 'Replace the access and refresh token lifetimes. Applies to tokens issued from now on; a token already issued keeps the expiry it was signed with. The change reaches every replica within its reload interval, or at once where a change signal is available'                                                                           , 'PUT'   , '/auth/token_lifetimes'                       , TRUE    ),
('019822af-b448-7576-8a41-41b83b3239f0', 'Resend verification email'           , 'Request a new verification email for unverified account.'                                                                                                                                                                                                                                                                               , 'POST'  , '/auth/verify'                                , TRUE    ),
('01a02dbb-bc41-7287-9cfd-7ac08bf882ae', 'Confirm email verification'          , 'Activate a user account with the verification token from the email. The token travels in the Authorization header, never in the URL.'                                                                                                                                                                                                   , 'POST'  , '/auth/verify/confirm'                        , TRUE    ),
('01982304-a1b2-7eec-8bf3-84f51fd09b74', 'Readiness probe and detailed health' , 'Per-component health, database pool stats and startup metrics, with the status code carrying the verdict: 200 healthy, 206 degraded, 503 a hard dependency is unreachable. This is the READINESS target — it answers whether this instance should receive traffic. Point liveness at /health/live, which deliberately checks nothing.'  , 'GET'   , '/health/detailed'                            , TRUE    ),
('01a02ec9-ac6c-77c2-81ad-d6e2f23bcd92', 'Liveness probe'                      , 'Answers 200 whenever this process can serve HTTP. It checks NOTHING else — no database, no cache — on purpose: a liveness probe decides whether to RESTART the process, and restarting cannot fix a dependency that is down. Point a readiness probe at /health/detailed instead, which does reflect dependencies.'                     , 'GET'   , '/health/live'                                , TRUE    ),
('0199489b-f2f0-718a-a0cb-de8752ea864f', 'Get authenticated user'              , 'Retrieve the profile information for the currently authenticated user'                                                                                                                                                                                                                                                                  , 'GET'   , '/me'                                         , TRUE    ),
('0199489b-f2f0-718e-a94d-b05a296eb818', 'Update authenticated user'           , 'Update the profile information for the currently authenticated user'                                                                                                                                                                                                                                                                    , 'PUT'   , '/me'                                         , TRUE    ),
('0199489b-f2f0-719e-b860-3b7ea6a86a1a', 'Get authorization info'              , 'Retrieve the authorization details and permissions for the currently authenticated user'                                                                                                                                                                                                                                                , 'GET'   , '/me/authz'                                   , TRUE    ),
('01a07319-1d32-7ca7-834a-d8dcc6a19fa0', 'List my linked identities'           , 'The identity providers the signed-in account can sign in through'                                                                                                                                                                                                                                                                       , 'GET'   , '/me/identities'                              , TRUE    ),
('01a07319-1d32-7cac-885b-6c544f5dbe08', 'Unlink my identity'                  , 'Remove the identity at one provider from the signed-in account. Refused when it is the only way into an account that has no password'                                                                                                                                                                                                   , 'DELETE', '/me/identities/{idp_id}'                     , TRUE    ),
('01a01117-dba9-74da-bd70-d1acc3842ffa', 'Get my resource limits'              , 'Retrieve the limits that apply to the calling user and how much of each has been consumed. Read-only: limits are not editable through the API.'                                                                                                                                                                                         , 'GET'   , '/me/resources_limits'                        , TRUE    ),
('01982303-f0f9-7ee4-968d-ba2078a272fc', 'List policies'                       , 'Retrieve a paginated list of all authorization policies in the system'                                                                                                                                                                                                                                                                  , 'GET'   , '/policies'                                   , TRUE    ),
('01982303-f0f9-7e38-ab68-486c8a2e819b', 'Create policy'                       , 'Create a new authorization policy with specified permissions'                                                                                                                                                                                                                                                                           , 'POST'  , '/policies'                                   , TRUE    ),
('01982303-f0f9-7f13-a03b-ed306ff7d06b', 'Delete policy'                       , 'Permanently remove an authorization policy by its unique identifier'                                                                                                                                                                                                                                                                    , 'DELETE', '/policies/{policy_id}'                       , TRUE    ),
('01982303-f0f9-7e30-ab3f-9220a73b02eb', 'Get policy'                          , 'Retrieve a specific authorization policy by its unique identifier'                                                                                                                                                                                                                                                                      , 'GET'   , '/policies/{policy_id}'                       , TRUE    ),
('01982303-f0f9-7ec1-8f39-98e77141c05c', 'Update policy'                       , 'Update an existing authorization policy by its unique identifier'                                                                                                                                                                                                                                                                       , 'PUT'   , '/policies/{policy_id}'                       , TRUE    ),
('01982303-f0f9-7ed4-9630-b9af3e3b6f17', 'Unlink roles from policy'            , 'Remove role associations from a specific policy'                                                                                                                                                                                                                                                                                        , 'DELETE', '/policies/{policy_id}/roles'                 , TRUE    ),
('01982303-f0f9-7ef0-ad95-3cb214216ef1', 'List roles by policy'                , 'Retrieve paginated list of roles associated with policy'                                                                                                                                                                                                                                                                                , 'GET'   , '/policies/{policy_id}/roles'                 , TRUE    ),
('01982303-f0f9-7e0d-ab27-f75b3a03ef46', 'Link roles to policy'                , 'Associate multiple roles with a specific policy for authorization'                                                                                                                                                                                                                                                                      , 'POST'  , '/policies/{policy_id}/roles'                 , TRUE    ),
('01982303-f0f9-7e63-92ba-141813745b06', 'List products'                       , 'List products across every project, with filtering, sorting, partial fields and pagination.'                                                                                                                                                                                                                                            , 'GET'   , '/products'                                   , TRUE    ),
('01982303-f0f9-7dbf-9688-6ef0150502e9', 'List projects'                       , 'Retrieve paginated list of accessible projects for authenticated user.'                                                                                                                                                                                                                                                                 , 'GET'   , '/projects'                                   , TRUE    ),
