('01982303-f0f9-7e9f-9bb9-81d42a9eb30a', 'Delete project'                      , 'Permanently remove project and all associated data.'                                                                                                                                                                                                                                                                                    , 'DELETE', '/projects/{project_id}'                      , TRUE    ),
('01982303-f0f9-7dfa-966c-4b9ce4133a33', 'Get project'                         , 'Retrieve project details by unique identifier.'                                                                                                                                                                                                                                                                                         , 'GET'   , '/projects/{project_id}'                      , TRUE    ),
