('01982303-f0f9-7e63-92ba-141813745b05', 'List products by project'            , 'List the products of one project, with filtering, sorting, partial fields and pagination.'                                                                                                                                                                                                                                              , 'GET'   , '/projects/{project_id}/products'             , TRUE    ),
('01982303-f0f9-7e63-92ba-141813745b01', 'Create product'                      , 'Create a new product inside a project. The name must be unique within the project.'                                                                                                                                                                                                                                                     , 'POST'  , '/projects/{project_id}/products'             , TRUE    ),
('01982303-f0f9-7e63-92ba-141813745b04', 'Delete product'                      , 'Delete a product from a project.'                                                                                                                                                                                                                                                                                                       , 'DELETE', '/projects/{project_id}/products/{product_id}', TRUE    ),
