('01a03a46-16d4-7b0a-af95-6805d68a37d3', 'Update rate limit'                   , 'Replace a rate-limit rule. The window set is replaced in full, not merged'                                                                                                                                                                                                                                                              , 'PUT'   , '/rate_limits/{rate_limit_id}'                , TRUE    ),
('01982303-f0f9-7ee0-aa66-0f756c3c8bec', 'List resources'                      , 'Retrieve a paginated list of all available system resources.'                                                                                                                                                                                                                                                                           , 'GET'   , '/resources'                                  , TRUE    ),
('01982303-f0f9-7e44-aeb1-63934913e601', 'Find resources by action and pattern', 'Retrieve a paginated list of resources that match the specified action and resource policy patterns.'                                                                                                                                                                                                                                   , 'GET'   , '/resources/matches'                          , TRUE    ),
('019822c9-9775-71b1-a2c6-deac83cf2519', 'Get resource'                        , 'Retrieve detailed information about a specific system resource configuration using its unique identifier.'                                                                                                                                                                                                                              , 'GET'   , '/resources/{resource_id}'                    , TRUE    ),
('01994754-5db8-7904-80f3-91417f2a4003', 'List resource limits'                , 'Retrieve a paginated list of resource limits in the system with optional filtering, sorting, and field selection'                                                                                                                                                                                                                       , 'GET'   , '/resources_limits'                           , TRUE    ),
('01982303-f0fa-703a-92fa-be272044b2e3', 'List roles'                          , 'Retrieve paginated list of roles with filtering and sorting'                                                                                                                                                                                                                                                                            , 'GET'   , '/roles'                                      , TRUE    ),
('01982303-f0f9-7eff-825d-622a05ef4435', 'Create role'                         , 'Create new role with specified permissions and access levels'                                                                                                                                                                                                                                                                           , 'POST'  , '/roles'                                      , TRUE    ),
