('01982303-f0f9-7dde-ab91-1ab138a8b6c5', 'Get role'                            , 'Retrieve role configuration by unique identifier'                                                                                                                                                                                                                                                                                       , 'GET'   , '/roles/{role_id}'                            , TRUE    ),
('01982303-f0f9-7e92-bd69-076fc1cd4a6e', 'Update role'                         , 'Update existing role configuration by identifier'                                                                                                                                                                                                                                                                                       , 'PUT'   , '/roles/{role_id}'                            , TRUE    ),
