('0199489b-f2f0-717a-8ee4-5814d4fa1c61', '0199489b-f2f0-718a-a0cb-de8752ea864f', 'Allow me Information', 'Allow get user information', 'GET', '/me', TRUE),
('0199489b-f2f0-718e-a94d-b05a296eb818', '0199489b-f2f0-718e-a94d-b05a296eb818', 'Allow update my information', 'Allow update my information', 'PUT', '/me', TRUE),
-- Allow reset password
('01991b30-2c97-7d5d-a426-7bb7f7c84775', '01991917-2720-758d-8104-94a0368acecb', 'Allow reset password', 'Allow reset password', 'POST', '/auth/password/reset', TRUE),
-- Allow list users
('019ab091-fb85-7b0c-bfec-673266ed8bd0', '01982303-f0f9-7daf-809b-4f7880ca9e40', 'Allow list users', 'Allow list users', 'GET', '/users', TRUE),
-- Seeing your own limits is granted to every authenticated user, exactly as GET /me and
-- GET /me/authz already are: a user who cannot find out why a creation was refused has to guess.
-- The project endpoint (/projects/{project_id}/resources_limits) deliberately gets no blanket
-- grant — project access is granted per user through roles and policies at runtime, the same as
-- every other /projects/{project_id}/... route.
('01a01119-62f4-7a96-9d4a-41c2f56e4086', '01a01117-dba9-74da-bd70-d1acc3842ffa', 'Allow me Resource Limits', 'Allow reading my own resource limits and usage', 'GET', '/me/resources_limits', TRUE),
-- Linking an identity provider to one's own account, and seeing / removing the links. Every
-- signed-in user may do this: the session proves the account, the provider proves the identity.
('01a07576-4ce5-74fd-9e86-ad854feecf73', '01a07319-1d32-7bd2-8ba0-f7da9aaaed0a', 'Allow me Link Identity', 'Allow linking an identity provider to my own account', 'GET', '/auth/idp/*/link', TRUE),
('01a07576-4ce5-75b2-ac8e-0c24302f69c5', '01a07319-1d32-7ca7-834a-d8dcc6a19fa0', 'Allow me Identities', 'Allow listing the identity providers linked to my account', 'GET', '/me/identities', TRUE),
('01a07576-4ce5-75b6-a9b0-efaaf510c9ee', '01a07319-1d32-7cac-885b-6c544f5dbe08', 'Allow me Unlink Identity', 'Allow removing an identity provider from my account', 'DELETE', '/me/identities/*', TRUE);

