-- +goose StatementBegin

-- Link tables first, then the rows they reference. Every seeded row is system = TRUE, and
-- fn_restrict_delete_update_on_system rejects DELETE as well as
-- UPDATE — so the flag cannot be cleared first and the triggers have to be disabled.
--
DELETE FROM users_roles;
DELETE FROM roles_policies;

ALTER TABLE policies DISABLE TRIGGER tr_restrict_delete_update_on_system_policies;
DELETE FROM policies;
ALTER TABLE policies ENABLE TRIGGER tr_restrict_delete_update_on_system_policies;

ALTER TABLE resources DISABLE TRIGGER tr_restrict_delete_update_on_system_resources;
DELETE FROM resources;
ALTER TABLE resources ENABLE TRIGGER tr_restrict_delete_update_on_system_resources;

ALTER TABLE roles DISABLE TRIGGER tr_restrict_delete_update_on_system_roles;
DELETE FROM roles;
ALTER TABLE roles ENABLE TRIGGER tr_restrict_delete_update_on_system_roles;

-- +goose StatementEnd
